0213 | \title[Universality for non-Hermitian matrices]{Random matrices: Universality of local spectral statistics of non-Hermitian matrices}
0214 | 
0215 | \author{Terence Tao}
0216 | \address{Department of Mathematics, UCLA, Los Angeles CA 90095-1555}
0217 | \email{[contact removed]}
0218 | \thanks{T. Tao is supported by NSF grant DMS-0649473.}
0219 | 
0220 | \author{Van Vu}
0221 | \address{Department of Mathematics, Rutgers, Piscataway, NJ 08854}
0222 | \email{[contact removed]}
